import re, os, collections
root='AlgebraicJacobian'
def path_of(mod):
    return mod.replace('.', '/')+'.lean'
def imports(f):
    out=[]
    try:
        for line in open(f, encoding='utf-8'):
            m=re.match(r'^import\s+(\S+)', line)
            if m: out.append(m.group(1))
            elif line.strip() and not line.startswith('/-') and not line.startswith('--') and re.match(r'^(set_option|namespace|open|universe|/-!)', line):
                break
    except FileNotFoundError:
        pass
    return out
def closure(start):
